<template><div class="page"><div class="page-title"><h2>订单全链路追踪</h2></div><div class="toolbar"><el-input v-model="keyword" placeholder="订单号 / 关键词" clearable @keyup.enter="load" /><el-select v-model="status" clearable placeholder="订单状态" style="width:150px"><el-option v-for="item in ['PAID','AUDITED','SHIPPED','COMPLETED']" :key="item" :label="item" :value="item" /></el-select><el-button type="primary" @click="load">查询</el-button></div><div class="panel"><el-table :data="rows" stripe><el-table-column prop="orderNo" label="订单号" /><el-table-column prop="status" label="状态" /><el-table-column prop="stage" label="当前阶段" /><el-table-column prop="warehouseCode" label="仓库" /><el-table-column prop="stuckHours" label="卡滞小时" /><el-table-column label="操作" width="100"><template #default="{ row }"><el-button link type="primary" @click="open(row.orderNo)">详情</el-button></template></el-table-column></el-table></div><el-drawer v-model="visible" title="订单详情" size="620px"><pre class="detail">{{ JSON.stringify(detail, null, 2) }}</pre></el-drawer></div></template>
<script setup>
import { ref } from 'vue'; import { traceApi } from '../api'
const rows = ref([]); const keyword = ref(''); const status = ref(''); const visible = ref(false); const detail = ref({})
async function load() { rows.value = await traceApi.page({ keyword: keyword.value, status: status.value }) }; async function open(id) { detail.value = await traceApi.detail(id); visible.value = true }; load()
</script>
<style scoped>.detail { white-space:pre-wrap; font-size:12px; background:#f7f8fa; padding:12px; border-radius:6px; }</style>
